using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Scenarios;

namespace OptimizingEfCoreQueries.Benchmarks;

// Both Baseline and Optimized query the SAME database, whose model already
// indexes Order.CreatedAt (DayIndexedContext). Baseline filters with a
// non-sargable CreatedAt.Date == day predicate that cannot use that index;
// Optimized calls the agent-owned SargableDaySolution.Run. Do not edit this file
// — edit Scenarios/SargableDay.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class SargableDayBenchmark
{
    // Orders are seeded starting 2020-01-01 at one-minute steps, so this day sits
    // comfortably inside the seeded range.
    private static readonly DateTime Day = new(2020, 2, 1);

    private SqliteConnection _connection = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using (var db = CreateIndexed(_connection))
        {
            db.Database.EnsureCreated();
            SeedData.SeedOrders(db, orders: 200000);
        }

        EquivalenceGuard.SameResults(Baseline(), Optimized(), id => id.ToString());
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<int> Baseline()
    {
        using var db = CreateIndexed(_connection);
        return db.Orders
            .Where(o => o.CreatedAt.Date == Day.Date)
            .OrderBy(o => o.Id)
            .Select(o => o.Id)
            .ToList();
    }

    [Benchmark]
    public List<int> Optimized()
    {
        using var db = CreateIndexed(_connection);
        return SargableDaySolution.Run(db, Day);
    }

    private static DayIndexedContext CreateIndexed(SqliteConnection connection) =>
        new(new DbContextOptionsBuilder<DayIndexedContext>().UseSqlite(connection).Options);
}

// A distinct context type whose model indexes Order.CreatedAt, so the index is
// present for both the baseline and the optimized query; only the predicate shape
// decides whether it can be used.
public class DayIndexedContext : AppDbContext
{
    public DayIndexedContext(DbContextOptions<DayIndexedContext> options) : base(options)
    {
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);
        modelBuilder.Entity<Order>().HasIndex(o => o.CreatedAt);
    }
}
